args.sql:
SELECT COUNT(*) FROM commerceandcollection c 
JOIN membershipandspending m ON c.commerce_member_pivot = m.member_reg 
WHERE (c.dig_own + c.phys_own) > 50 AND c.coll_comp_rate > 75;
